//! Static assets embedded in the binary: one self-contained artifact, no runtime file paths, no
//! directory-traversal surface. `app.css` and `app.js` are addressed with a content-hash query
//! (`?v=…`) so they can be cached as immutable; fonts and the favicon have stable names.
//!
//! `assets/app.css` is generated by `just css` from `style/tailwind.css` and committed;
//! `just css-check` (CI) fails if it is stale.

/// One embedded file.
#[derive(Clone, Copy, Debug)]
pub struct Asset {
    /// Path below `/assets/`.
    pub path: &'static str,
    pub mime: &'static str,
    pub bytes: &'static [u8],
    /// Whether the URL carries a content hash and may be cached as immutable.
    pub versioned: bool,
}

#[allow(clippy::cast_lossless)] // `u64::from` is not callable in a const fn
const fn fnv1a(bytes: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    let mut i = 0;
    while i < bytes.len() {
        hash ^= bytes[i] as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        i += 1;
    }
    hash
}

impl Asset {
    /// Short content hash (16 hex digits).
    #[must_use]
    pub fn version(&self) -> String {
        format!("{:016x}", fnv1a(self.bytes))
    }

    /// URL to reference from HTML: includes `?v=<hash>` for versioned assets.
    #[must_use]
    pub fn url(&self) -> String {
        if self.versioned {
            format!("/assets/{}?v={}", self.path, self.version())
        } else {
            format!("/assets/{}", self.path)
        }
    }
}

pub const APP_CSS: Asset = Asset {
    path: "app.css",
    mime: "text/css; charset=utf-8",
    bytes: include_bytes!("../assets/app.css"),
    versioned: true,
};
pub const APP_JS: Asset = Asset {
    path: "app.js",
    mime: "text/javascript; charset=utf-8",
    bytes: include_bytes!("../assets/app.js"),
    versioned: true,
};
pub const FAVICON: Asset = Asset {
    path: "favicon.svg",
    mime: "image/svg+xml",
    bytes: include_bytes!("../assets/favicon.svg"),
    versioned: false,
};
/// Fonts keep stable names: rename the file when the font data changes.
pub const FONT_REGULAR: Asset = Asset {
    path: "fonts/BeVietnamPro-Regular.woff",
    mime: "font/woff",
    bytes: include_bytes!("../assets/fonts/BeVietnamPro-Regular.woff"),
    versioned: false,
};
pub const FONT_SEMIBOLD: Asset = Asset {
    path: "fonts/BeVietnamPro-SemiBold.woff",
    mime: "font/woff",
    bytes: include_bytes!("../assets/fonts/BeVietnamPro-SemiBold.woff"),
    versioned: false,
};
pub const FONT_LICENSE: Asset = Asset {
    path: "fonts/OFL.txt",
    mime: "text/plain; charset=utf-8",
    bytes: include_bytes!("../assets/fonts/OFL.txt"),
    versioned: false,
};

/// Every servable asset.
pub const ALL: [Asset; 6] = [
    APP_CSS,
    APP_JS,
    FAVICON,
    FONT_REGULAR,
    FONT_SEMIBOLD,
    FONT_LICENSE,
];

/// Looks up an asset by its path below `/assets/`. Exact match only: no normalisation, so
/// `..`, encoded separators and unknown names all miss.
#[must_use]
pub fn find(path: &str) -> Option<&'static Asset> {
    ALL.iter().find(|a| a.path == path)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn paths_are_unique_and_found() {
        for a in &ALL {
            assert_eq!(find(a.path).map(|f| f.path), Some(a.path));
            assert!(!a.bytes.is_empty(), "{} is empty", a.path);
        }
        let mut paths: Vec<_> = ALL.iter().map(|a| a.path).collect();
        paths.sort_unstable();
        paths.dedup();
        assert_eq!(paths.len(), ALL.len());
    }

    #[test]
    fn lookup_is_exact() {
        for bad in [
            "",
            "../app.css",
            "app.css/",
            "/app.css",
            "fonts/../app.css",
            "APP.CSS",
            "%2e%2e/app.css",
        ] {
            assert!(find(bad).is_none(), "{bad:?} must not resolve");
        }
    }

    #[test]
    fn versioned_urls_change_with_content() {
        assert!(APP_CSS.url().starts_with("/assets/app.css?v="));
        assert_eq!(
            FONT_REGULAR.url(),
            "/assets/fonts/BeVietnamPro-Regular.woff"
        );
        assert_eq!(fnv1a(b""), 0xcbf2_9ce4_8422_2325);
        assert_ne!(fnv1a(b"a"), fnv1a(b"b"));
    }

    #[test]
    fn css_is_csp_friendly_and_self_contained() {
        let css = std::str::from_utf8(APP_CSS.bytes).expect("css is utf-8");
        assert!(
            !css.contains("data:"),
            "data: URLs would need a relaxed img/font CSP"
        );
        // Every url(...) must point at our own /assets/ (the licence comment may mention a URL).
        for chunk in css.split("url(").skip(1) {
            let target = chunk.trim_start_matches(['"', '\'']);
            assert!(
                target.starts_with("/assets/"),
                "css references a non-local url: {}",
                &chunk[..chunk.len().min(60)]
            );
        }
        assert!(!css.contains("@import url"), "no remote @import");
        for font in [FONT_REGULAR, FONT_SEMIBOLD] {
            assert!(
                css.contains(&format!("/assets/{}", font.path)),
                "css must reference {}",
                font.path
            );
        }
        assert!(css.len() > 5_000, "css looks empty; run `just css`");
    }

    #[test]
    fn js_has_no_eval_and_no_inline_handlers_needed() {
        let js = std::str::from_utf8(APP_JS.bytes).expect("js is utf-8");
        for banned in ["eval(", "new Function", "innerHTML", "document.write"] {
            assert!(!js.contains(banned), "app.js must not use {banned}");
        }
    }
}
